import express from 'express';
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_DIR = join(__dirname, 'data');
const DATA_FILE = join(DATA_DIR, 'books.json');
const PUBLIC_DIR = join(__dirname, 'public');

const app = express();
app.use(express.json());
app.use(express.static(PUBLIC_DIR));

function loadBooks() {
  if (!existsSync(DATA_FILE)) {
    mkdirSync(DATA_DIR, { recursive: true });
    writeFileSync(DATA_FILE, JSON.stringify({ books: [] }, null, 2));
  }
  return JSON.parse(readFileSync(DATA_FILE, 'utf8'));
}

function saveBooks(data) {
  writeFileSync(DATA_FILE, JSON.stringify(data, null, 2));
}

app.get('/api/books', (_req, res) => {
  res.json(loadBooks().books);
});

app.get('/api/books/:id', (req, res) => {
  const book = loadBooks().books.find((b) => b.id === req.params.id);
  if (!book) return res.status(404).json({ error: 'Book not found' });
  res.json(book);
});

app.post('/api/books', (req, res) => {
  const { title, author, notes } = req.body;
  if (!title?.trim() || !author?.trim()) {
    return res.status(400).json({ error: 'Title and author are required' });
  }

  const book = {
    id: randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes?.trim() || '',
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };

  const data = loadBooks();
  data.books.unshift(book);
  saveBooks(data);
  res.status(201).json(book);
});

app.patch('/api/books/:id', (req, res) => {
  const data = loadBooks();
  const index = data.books.findIndex((b) => b.id === req.params.id);
  if (index === -1) return res.status(404).json({ error: 'Book not found' });

  const book = data.books[index];
  if (req.body.status === 'finished' && book.status !== 'finished') {
    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
  }
  if (typeof req.body.notes === 'string') {
    book.notes = req.body.notes.trim();
  }

  data.books[index] = book;
  saveBooks(data);
  res.json(book);
});

app.get('/book/:id', (_req, res) => {
  res.sendFile(join(PUBLIC_DIR, 'book.html'));
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Reading list running at http://localhost:${PORT}`);
});

