*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --bg: #f7f3ed;
  --surface: #fffdf9;
  --text: #2c2416;
  --muted: #6b5f4e;
  --accent: #8b4513;
  --accent-hover: #6d3610;
  --border: #e0d6c8;
  --reading: #2d6a4f;
  --finished: #6b5f4e;
  --shadow: 0 1px 3px rgba(44, 36, 22, 0.08);
}

body {
  margin: 0;
  font-family: Georgia, 'Times New Roman', serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

header {
  margin-bottom: 2rem;
}

header h1 {
  margin: 0;
  font-size: 1.75rem;
  font-weight: normal;
  letter-spacing: -0.02em;
}

header p {
  margin: 0.35rem 0 0;
  color: var(--muted);
  font-size: 0.95rem;
}

section {
  margin-bottom: 2.5rem;
}

section h2 {
  font-size: 0.8rem;
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin: 0 0 0.75rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--border);
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1rem 1.1rem;
  margin-bottom: 0.6rem;
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.card-info {
  flex: 1;
  min-width: 0;
}

.card-title {
  font-size: 1.05rem;
  margin: 0;
}

.card-title a {
  color: inherit;
  text-decoration: none;
}

.card-title a:hover {
  color: var(--accent);
  text-decoration: underline;
}

.card-author {
  margin: 0.15rem 0 0;
  font-size: 0.9rem;
  color: var(--muted);
}

.empty {
  color: var(--muted);
  font-style: italic;
  font-size: 0.95rem;
  margin: 0;
}

form.add-book {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1.25rem;
  margin-bottom: 2.5rem;
  box-shadow: var(--shadow);
}

form.add-book h2 {
  margin: 0 0 1rem;
  font-size: 1rem;
  font-weight: normal;
  text-transform: none;
  letter-spacing: 0;
  color: var(--text);
  border: none;
  padding: 0;
}

.field {
  margin-bottom: 0.85rem;
}

.field label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.3rem;
}

.field input,
.field textarea {
  width: 100%;
  font: inherit;
  font-family: system-ui, sans-serif;
  font-size: 0.95rem;
  padding: 0.5rem 0.65rem;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: #fff;
  color: var(--text);
}

.field textarea {
  resize: vertical;
  min-height: 4rem;
}

.field input:focus,
.field textarea:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

button,
.btn {
  font: inherit;
  font-family: system-ui, sans-serif;
  font-size: 0.85rem;
  cursor: pointer;
  border-radius: 4px;
  padding: 0.45rem 0.85rem;
  border: 1px solid transparent;
  transition: background 0.15s;
}

button.primary,
.btn.primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

button.primary:hover,
.btn.primary:hover {
  background: var(--accent-hover);
}

button.secondary,
.btn.secondary {
  background: transparent;
  color: var(--reading);
  border-color: var(--reading);
}

button.secondary:hover,
.btn.secondary:hover {
  background: rgba(45, 106, 79, 0.08);
}

.book-detail {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.book-detail h1 {
  margin: 0;
  font-size: 1.6rem;
  font-weight: normal;
}

.book-detail .author {
  margin: 0.4rem 0 0;
  font-size: 1.05rem;
  color: var(--muted);
}

.book-detail .status-badge {
  display: inline-block;
  margin-top: 1rem;
  font-family: system-ui, sans-serif;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 0.2rem 0.55rem;
  border-radius: 3px;
}

.status-badge.reading {
  background: rgba(45, 106, 79, 0.12);
  color: var(--reading);
}

.status-badge.finished {
  background: rgba(107, 95, 78, 0.12);
  color: var(--finished);
}

.book-detail .notes {
  margin-top: 1.5rem;
  padding-top: 1.25rem;
  border-top: 1px solid var(--border);
}

.book-detail .notes h2 {
  font-size: 0.8rem;
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin: 0 0 0.5rem;
  border: none;
  padding: 0;
}

.book-detail .notes p {
  margin: 0;
  white-space: pre-wrap;
}

.book-detail .notes .empty {
  font-style: italic;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.25rem;
  font-family: system-ui, sans-serif;
  font-size: 0.9rem;
}

.error-message {
  color: #9b2226;
  font-family: system-ui, sans-serif;
  font-size: 0.9rem;
}

