:root {
  --bg: #f7f3ed;
  --surface: #fffdf9;
  --text: #2c2416;
  --muted: #6b5f4e;
  --accent: #8b4513;
  --accent-hover: #6d3610;
  --border: #e0d6c8;
  --reading: #2d6a4f;
  --finished: #6b5f4e;
  --shadow: 0 1px 3px rgba(44, 36, 22, 0.08);
}

body {
  margin: 0;
  font-family: Georgia, 'Times New Roman', serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

header {
  margin-bottom: 2rem;
}

header h1 {
  margin: 0;
  font-size: 1.75rem;
  font-weight: normal;
  letter-spacing: -0.02em;
}

