  margin: 0.35rem 0 0;
  color: var(--muted);
  font-size: 0.95rem;
}

section {
  margin-bottom: 2.5rem;
}

section h2 {
  font-size: 0.8rem;
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
