function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

function bookCard(book, { showFinishButton = false } = {}) {
  const card = document.createElement('div');
  card.className = 'card';
  card.innerHTML = `
    <div class="card-info">
      <p class="card-title"><a href="/book/${book.id}">${escapeHtml(book.title)}</a></p>
      <p class="card-author">${escapeHtml(book.author)}</p>
    </div>
  `;

  if (showFinishButton) {
    const btn = document.createElement('button');
    btn.className = 'secondary';
    btn.textContent = 'Mark finished';
    btn.addEventListener('click', async () => {
      btn.disabled = true;
      await fetch(`/api/books/${book.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' }),
      });
      loadBooks();
    });
    card.appendChild(btn);
  }

  return card;
}

function renderList(container, books, options) {
  container.innerHTML = '';
  if (books.length === 0) {
    const p = document.createElement('p');
    p.className = 'empty';
    p.textContent = options.emptyText;
    container.appendChild(p);
    return;
  }
  for (const book of books) {
    container.appendChild(bookCard(book, options));
  }
}

async function loadBooks() {
  const res = await fetch('/api/books');
  const books = await res.json();

  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  renderList(document.getElementById('reading-list'), reading, {
    showFinishButton: true,
    emptyText: 'Nothing on the go right now.',
  });

  renderList(document.getElementById('finished-list'), finished, {
    emptyText: 'No finished books yet.',
  });
}

document.getElementById('add-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const form = e.target;
  const title = form.title.value;
  const author = form.author.value;
  const notes = form.notes.value;

  const res = await fetch('/api/books', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, author, notes }),
  });

  if (res.ok) {
    form.reset();
    loadBooks();
  }
});

loadBooks();

